{
  "missionStatement": "Study superconducting materials via web research and update the repository with proposed chemistry and physics for discovering and manufacturing room-temperature superconducting compounds.",
  "criteria": [
    {
      "description": "Literature review is updated with at least 5 recent papers (2020+) on room-temperature superconductivity, including hydrides, nickelates, and other candidate systems, with citations and key findings.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "Theoretical framework document includes a proposed mechanism for room-temperature superconductivity, citing BCS theory extensions, strong coupling, or other models, and discusses implications for material design.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "Candidate materials document lists at least 3 new compounds with predicted Tc > 300K, including synthesis routes, challenges, and references to literature.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Synthesis methods document includes scalable manufacturing approaches such as high-pressure synthesis, chemical vapor deposition, or thin-film growth, with step-by-step procedures for at least one candidate.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Manufacturing scalability document outlines a step-by-step process for producing a chosen compound at scale, with cost and feasibility analysis, and identifies key challenges.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "A new document 'discovery_strategy.md' is created that outlines a systematic approach to discover new room-temperature superconductors using machine learning, high-throughput screening, or combinatorial chemistry.",
      "expectedFiles": ["discovery_strategy.md"]
    },
    {
      "description": "Characterization techniques document is updated with modern methods for verifying room-temperature superconductivity, including transport, magnetic, and spectroscopic techniques, with emphasis on distinguishing from other phenomena.",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "The predict_tc.py script is executed on candidate materials from the database and literature, and the resulting Tc predictions are incorporated into candidate_materials.md with a table of predicted values.",
      "expectedFiles": ["candidate_materials.md", "scripts/predict_tc.py"]
    },
    {
      "description": "Roadmap document is updated with new milestones for the next 6 months, including experimental validation of proposed compounds, collaboration with synthesis labs, and publication targets.",
      "expectedFiles": ["roadmap.md"]
    }
  ]
}

{
  "missionStatement": "Conduct online research on room-temperature superconductivity and update the repository with new chemistry, physics, and manufacturing insights to guide discovery and synthesis of room-temperature superconducting compounds.",
  "criteria": [
    {
      "description": "Perform at least 5 targeted web searches on room-temperature superconductors (e.g., hydrides, nickelates, BCS theory, high-pressure synthesis) and document key findings.",
      "expectedFiles": []
    },
    {
      "description": "Update literature_review.md with recent (2020+) papers, including hydride superconductivity, carbonaceous sulfur hydride, and lanthanum hydride, with citations and summaries.",
      "expectedFiles": ["literature_review.md"]
    },
    {
      "description": "Update theoretical_framework.md to include BCS theory, Eliashberg equations, and mechanisms for high-Tc in hydrogen-rich materials, with references.",
      "expectedFiles": ["theoretical_framework.md"]
    },
    {
      "description": "Update candidate_materials.md with new promising compounds (e.g., LaH10, H3S, C-S-H, YNi2B2C) and their predicted Tc, synthesis conditions, and stability.",
      "expectedFiles": ["candidate_materials.md"]
    },
    {
      "description": "Update synthesis_methods.md with high-pressure diamond anvil cell techniques, laser heating, and chemical vapor deposition for hydrogen-rich materials.",
      "expectedFiles": ["synthesis_methods.md"]
    },
    {
      "description": "Update characterization_techniques.md with methods for measuring Tc under pressure (e.g., four-probe resistance, AC susceptibility, X-ray diffraction).",
      "expectedFiles": ["characterization_techniques.md"]
    },
    {
      "description": "Update roadmap.md with new milestones for computational screening, high-pressure synthesis, and scalability testing of candidate compounds.",
      "expectedFiles": ["roadmap.md"]
    },
    {
      "description": "Create a new document docs/manufacturing_scalability.md that outlines challenges and potential solutions for scaling up high-pressure synthesis to ambient conditions.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Create a new document docs/novel_mechanism.md that summarizes proposed mechanisms (e.g., phonon-mediated, excitonic, plasmonic) for room-temperature superconductivity.",
      "expectedFiles": ["docs/novel_mechanism.md"]
    },
    {
      "description": "Update data/superconductor_database.json with at least 5 new entries for recently discovered or predicted room-temperature superconductors, including Tc, pressure, and reference.",
      "expectedFiles": ["data/superconductor_database.json"]
    },
    {
      "description": "Update scripts/predict_tc.py to include a function that estimates Tc using the Allen-Dynes formula or a simple BCS model for hydrogen-rich materials.",
      "expectedFiles": ["scripts/predict_tc.py"]
    },
    {
      "description": "Update scripts/query_database.py to allow filtering by pressure range and Tc threshold, and add a command-line option to output results in markdown format.",
      "expectedFiles": ["scripts/query_database.py"]
    },
    {
      "description": "Add a new section to README.md that summarizes the latest research findings and directs readers to the updated documents.",
      "expectedFiles": ["README.md"]
    },
    {
      "description": "Create a new file docs/experimental_feedback_loop.md that describes an iterative process for computational prediction, synthesis, characterization, and refinement.",
      "expectedFiles": ["docs/experimental_feedback_loop.md"]
    }
  ]
}

